// LXG-01 · Config — EDIT THIS NODE to change Apollo targeting or run size.
// Everything operational (mode, caps) comes from environment variables so the
// owner never has to touch code for routine changes.
const mode = String($env.LEAD_SOURCE_MODE || 'csv').toLowerCase();      // 'apollo_api' | 'csv'
const maxPerRun = parseInt($env.APOLLO_MAX_PER_RUN || '50', 10);        // ramp-up control
const sd = $getWorkflowStaticData('global');
const page = parseInt(sd.apolloPage || '1', 10);

return [{ json: {
  mode,
  maxPerRun,
  page,
  // ---- Apollo "People API Search" parameters (used only when mode = apollo_api).
  // Parameter names follow Apollo's public docs; verify against your plan (see docs/apollo-setup.md).
  search: {
    person_titles: [
      'owner', 'founder', 'co-founder', 'director', 'managing director',
      'buyer', 'head of buying', 'purchasing manager', 'retail buyer', 'general manager'
    ],
    person_locations: ['United Kingdom'],
    q_organization_keyword_tags: [
      'golf', 'golf pro shop', 'country club', 'private members club', 'equestrian',
      'motorsport', 'boutique fitness', 'premium gym', 'gift shop', 'hotel gift shop',
      'yacht club', 'sailing club', 'sporting goods', 'menswear', 'lifestyle boutique'
    ],
    organization_num_employees_ranges: ['1,10', '11,50', '51,200'],
    page,
    per_page: Math.min(maxPerRun, 100)
  }
} }];

// LXG-01 · Collapse the Intake rows read from the sheet into ONE item that carries the run config forward,
// so downstream nodes run once (not once per existing row).
return [{ json: $('Config').first().json }];

// LXG-01 · Apollo: drop people we already ingested BEFORE spending enrichment credits,
// then split the rest into batches of 10 (bulk-match limit).
const res = $input.first().json || {};
const people = res.people || res.contacts || [];
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');

const known = new Set(
  $('Read Existing Intake').all().map(i => String(i.json['Apollo ID'] || '')).filter(Boolean)
);

// advance / reset the search page (persisted only on production runs)
sd.apolloPage = people.length ? cfg.page + 1 : 1;

const fresh = people.filter(p => p && p.id && !known.has(String(p.id))).slice(0, cfg.maxPerRun);
const batches = [];
for (let i = 0; i < fresh.length; i += 10) batches.push(fresh.slice(i, i + 10));
console.log(`Apollo search: ${people.length} returned, ${fresh.length} new, ${batches.length} enrichment batches`);
return batches.map(b => ({ json: { details: b.map(p => ({ id: p.id })) } }));

// LXG-01 · Apollo adapter output -> canonical lead shape.
// Only maps fields Apollo returns; anything missing stays blank (qualification decides).
const s = v => (v === null || v === undefined) ? '' : String(v).trim();
const host = u => s(u).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];

const out = [];
for (const it of $input.all()) {
  for (const m of (it.json.matches || it.json.people || [])) {
    if (!m) continue;
    const org = m.organization || {};
    const first = s(m.first_name), last = s(m.last_name);
    out.push({ json: {
      source: 'apollo_api',
      apollo_id: s(m.id),
      first_name: first,
      last_name: last,
      full_name: s(m.name) || `${first} ${last}`.trim(),
      job_title: s(m.title),
      company_name: s(org.name || m.organization_name),
      company_domain: s(org.primary_domain) || host(org.website_url),
      website: s(org.website_url),
      email: s(m.email).toLowerCase(),
      email_verification_status: s(m.email_status).toLowerCase(),
      industry: s(org.industry),
      company_type: [].concat(org.keywords || []).slice(0, 8).join(', ').slice(0, 200),
      country: s(m.country || org.country),
      city: s(m.city || org.city),
      employee_count: s(org.estimated_num_employees)
    } });
  }
}
return out;

// LXG-01 · CSV fallback adapter. Accepts an Apollo contact export (or any CSV using
// similar headers). Header matching ignores case, spaces and punctuation.
const s = v => (v === null || v === undefined) ? '' : String(v).trim();
const key = k => String(k).toLowerCase().replace(/[^a-z0-9]/g, '');
const host = u => s(u).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];

const ALIASES = {
  first_name: ['firstname'],
  last_name: ['lastname'],
  full_name: ['fullname', 'name'],
  job_title: ['title', 'jobtitle'],
  company_name: ['company', 'companyname', 'organization', 'companynameforemails'],
  company_domain: ['companydomain', 'domain', 'primarydomain'],
  website: ['website', 'companywebsite', 'websiteurl'],
  email: ['email', 'emailaddress', 'workemail'],
  email_verification_status: ['emailstatus', 'emailverificationstatus', 'verificationstatus'],
  industry: ['industry'],
  company_type: ['companytype', 'keywords', 'companykeywords'],
  country: ['country', 'companycountry'],
  city: ['city', 'companycity'],
  employee_count: ['employees', 'employeecount', 'numemployees', 'estimatednumemployees'],
  apollo_id: ['apollocontactid', 'apolloid', 'apolloaccountid']
};

const out = [];
for (const it of $input.all()) {
  const row = {};
  for (const [k, v] of Object.entries(it.json)) row[key(k)] = v;
  const pick = f => { for (const a of ALIASES[f]) if (row[a] !== undefined && s(row[a]) !== '') return s(row[a]); return ''; };
  const first = pick('first_name'), last = pick('last_name');
  const website = pick('website');
  if (!first && !last && !pick('email') && !pick('company_name')) continue;   // blank line
  out.push({ json: {
    source: 'csv',
    apollo_id: pick('apollo_id'),
    first_name: first,
    last_name: last,
    full_name: pick('full_name') || `${first} ${last}`.trim(),
    job_title: pick('job_title'),
    company_name: pick('company_name'),
    company_domain: (pick('company_domain') || host(website)).toLowerCase(),
    website,
    email: pick('email').toLowerCase(),
    email_verification_status: pick('email_verification_status').toLowerCase(),
    industry: pick('industry'),
    company_type: pick('company_type').slice(0, 200),
    country: pick('country'),
    city: pick('city'),
    employee_count: pick('employee_count')
  } });
}
return out;

// LXG-01 · Build Intake rows. Skips anything already in the Intake tab, caps the run size.
// NOTE: this is NOT the dedupe/qualification step (that is LXG-02); this only prevents
// re-importing the exact same source record over and over.
function hash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}
const cfg = $('Config').first().json;
const existing = new Set($('Read Existing Intake').all().map(i => i.json['Intake ID']).filter(Boolean));
const now = new Date().toISOString();
const rows = [];
let skipped = 0;

for (const { json: l } of $input.all()) {
  const natural = l.apollo_id || l.email || `${l.company_domain}|${l.full_name}`.toLowerCase();
  const id = 'IN-' + hash(`${l.source}|${natural}`);
  if (existing.has(id)) { skipped++; continue; }
  existing.add(id);
  if (rows.length >= cfg.maxPerRun) { skipped++; continue; }
  rows.push({ json: {
    'Intake ID': id, 'Date Added': now, 'Source': l.source, 'Apollo ID': l.apollo_id,
    'First Name': l.first_name, 'Last Name': l.last_name, 'Full Name': l.full_name,
    'Job Title': l.job_title, 'Company': l.company_name, 'Domain': l.company_domain,
    'Website': l.website, 'Email': l.email, 'Email Verification Status': l.email_verification_status,
    'Industry': l.industry, 'Company Type': l.company_type, 'Country': l.country, 'City': l.city,
    'Employee Count': l.employee_count, 'Intake Status': 'PENDING', 'Reason': '', 'Processed At': ''
  } });
}
console.log(`Intake: ${rows.length} new rows, ${skipped} skipped (already ingested or over per-run cap)`);
return rows;
